def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Connect diagonal pairs of 1s; a 6 on the segment extends along its
    # perpendicular diagonal.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc) or dr == 0:
                continue
            steps = abs(dr)
            sr = 1 if dr > 0 else -1
            sc = 1 if dc > 0 else -1

            segment = [(r1 + k * sr, c1 + k * sc) for k in range(steps + 1)]
            for r, c in segment:
                if grid[r][c] != 6:
                    out[r][c] = 1

            for r, c in sixes:
                if (r, c) not in segment:
                    continue
                # Perpendicular diagonal through this 6: row + col or
                # row - col remains constant.
                for rr in range(h):
                    if dr * dc > 0:
                        cc = r + c - rr
                    else:
                        cc = c - r + rr
                    if 0 <= cc < w and grid[rr][cc] != 1:
                        out[rr][cc] = 6

    return out

def transform(grid):
    from collections import defaultdict, Counter

    h, w = len(grid), len(grid[0])
    samples = defaultdict(Counter)

    # The patterned area has a constant color along each anti-diagonal.
    for r in range(3, h):
        for c in range(3, w):
            if grid[r][c] != 0:
                samples[r + c][grid[r][c]] += 1

    diagonal_color = {
        s: counts.most_common(1)[0][0]
        for s, counts in samples.items()
    }

    out = [row[:] for row in grid]
    known = sorted(diagonal_color)
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                s = r + c
                if s in diagonal_color:
                    out[r][c] = diagonal_color[s]
                elif known:
                    nearest = min(known, key=lambda k: abs(k - s))
                    out[r][c] = diagonal_color[nearest]
    return out

def transform(grid):
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]

    for r in range(n):
        for c in range(n):
            d = c - center
            if abs(d) == r:
                out[r][c] = 2
            elif abs(d) < r and (d - r) % 4 == 0:
                out[r][c] = 1

    return out

