            for i in range(4):
                for j in range(4):
                    if grid[r+i][c+j] == 2:
                        total += 1
                        sr += i
                        sc += j
            if total:
                dr = sr / total - 1.5
                dc = sc / total - 1.5
                block_r, block_c = r + 1.5, c + 1.5
