def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    enclosed = []
    exterior = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue

            stack = [(r, c)]
            seen[r][c] = True
            region = []
            touches_edge = False

            while stack:
                y, x = stack.pop()
                region.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] == 0 and not seen[ny][nx]):
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            (exterior if touches_edge else enclosed).append(region)

    out = [row[:] for row in grid]
    marked_ones = set()

    for region in enclosed:
        for r, c in region:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    out[r][c] = 3
                    marked_ones.add((nr, nc))

    # Include each complete 1-connected shape bordering an enclosed region.
    stack = list(marked_ones)
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                    and (nr, nc) not in marked_ones):
                marked_ones.add((nr, nc))
                stack.append((nr, nc))

    for region in exterior:
        for r, c in region:
            if any(
                0 <= r + dr < h and 0 <= c + dc < w
                and (r + dr, c + dc) in marked_ones
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            ):
                out[r][c] = 2

    return out

from math import gcd
from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    marker_cells = [
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] not in (0, 8)
    ]
    shape_cells = [
        (r, c) for r in range(h) for c in range(w) if grid[r][c] == 8
    ]
    if not marker_cells or not shape_cells:
        return out

    # The repeated square-unit size is the gcd of contiguous 8-run lengths.
    runs = []
    for line in (grid, list(map(list, zip(*grid)))):
        for row in line:
            n = 0
            for value in row:
                if value == 8:
                    n += 1
                elif n:
                    runs.append(n)
                    n = 0
            if n:
                runs.append(n)
    size = reduce(gcd, runs)

    sr0 = min(r for r, c in shape_cells)
    sc0 = min(c for r, c in shape_cells)
    mr0 = min(r for r, c in marker_cells)
    mc0 = min(c for r, c in marker_cells)
    mr1 = max(r for r, c in marker_cells)
    mc1 = max(c for r, c in marker_cells)

    pattern = [
        [grid[r][c] for c in range(mc0, mc1 + 1)]
        for r in range(mr0, mr1 + 1)
    ]
    # Rotate the small color pattern 90 degrees clockwise.
    pattern = [list(row) for row in zip(*pattern[::-1])]

    for r, c in shape_cells:
        br, bc = (r - sr0) // size, (c - sc0) // size
        if br < len(pattern) and bc < len(pattern[0]):
            color = pattern[br][bc]
            if color:
                out[r][c] = color

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]

    cells = [(r, c) for r in range(h) for c in range(w) if src[r][c] == 4]
    if not cells:
        return out

    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    shape = {(r - r0, c - c0) for r, c in cells}
    sh = max(r for r, c in shape) + 1
    sw = max(c for r, c in shape) + 1

    for color in range(10):
        if color in (1, 4):
            continue
        remaining = {(r, c) for r in range(h) for c in range(w)
                     if src[r][c] == color}

        while len(remaining) >= 2:
            candidates = set()
            for r, c in remaining:
                for dr, dc in shape:
                    ar, ac = r - dr, c - dc
                    if 0 <= ar and ar + sh <= h and 0 <= ac and ac + sw <= w:
                        candidates.add((ar, ac))

            best = None
            for ar, ac in candidates:
                matched = {(r, c) for r, c in remaining
                           if (r - ar, c - ac) in shape}
                if len(matched) < 2:
                    continue
                key = (-len(matched), ar, ac)
                if best is None or key < best[0]:
                    best = (key, ar, ac, matched)

            if best is None:
                break

            _, ar, ac, matched = best
            for dr, dc in shape:
                r, c = ar + dr, ac + dc
                if src[r][c] == 1:
                    out[r][c] = color
            remaining -= matched

    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the repeated barcode rows and read their colors left to right.
    barcode_rows = []
    start = end = None
    r = 0
    while r < h:
        sig = tuple((x, grid[r][x]) for x in range(w) if grid[r][x] != 0)
        if not sig:
            r += 1
            continue
        e = r + 1
        while e < h:
            next_sig = tuple((x, grid[e][x]) for x in range(w) if grid[e][x] != 0)
            if next_sig != sig:
                break
            e += 1
        if e - r >= 2 and (end is None or e - r > end - start):
            start, end = r, e
        r = e
    if start is not None:
        barcode_rows = list(range(start, end))
        sequence = []
        for v in grid[start]:
            if v and v not in sequence:
                sequence.append(v)
    else:
        return out

    # Find same-color objects using 8-connectivity (some motif cells touch diagonally).
    seen = set()
    comps = []
    for y in range(h):
        for x in range(w):
            color = grid[y][x]
            if color == 0 or (y, x) in seen:
                continue
            stack = [(y, x)]
            seen.add((y, x))
            cells = []
            while stack:
                cy, cx = stack.pop()
                cells.append((cy, cx))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = cy + dy, cx + dx
                        if (0 <= ny < h and 0 <= nx < w and
                                grid[ny][nx] == color and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            comps.append((color, cells))

    # Use the largest non-barcode object as the motif.
    candidates = [(c, cells) for c, cells in comps
                  if not all(y in barcode_rows for y, x in cells)]
    if not candidates:
        return out
    _, motif_cells = max(candidates, key=lambda item: len(item[1]))
    miny = min(y for y, x in motif_cells)
    maxy = max(y for y, x in motif_cells)
    minx = min(x for y, x in motif_cells)
    maxx = max(x for y, x in motif_cells)
    mh, mw = maxy - miny + 1, maxx - minx + 1
    mask = frozenset((y - miny, x - minx) for y, x in motif_cells)

    # Find existing copies of this motif and their top rows.
    tops = {}
    for color, cells in comps:
        if all(y in barcode_rows for y, x in cells):
            continue
        y0 = min(y for y, x in cells)
        y1 = max(y for y, x in cells)
        x0 = min(x for y, x in cells)
        x1 = max(x for y, x in cells)
        cmask = frozenset((y - y0, x - x0) for y, x in cells)
        if (y1 - y0 + 1, x1 - x0 + 1) == (mh, mw) and cmask == mask:
            tops[color] = y0

    # Remove the barcode and extend the motif stack in the barcode's color order.
    for y in barcode_rows:
        for x in range(w):
            if grid[y][x]:
                out[y][x] = 0

    known = next((c for c in sequence if c in tops), None)
    if known is not None:
        base = tops[known] - sequence.index(known) * mh
        for i, color in enumerate(sequence):
            top = base + i * mh
            for dy, dx in mask:
                y, x = top + dy, minx + dx
                if 0 <= y < h and 0 <= x < w:
                    out[y][x] = color
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    separators = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    bounds = [-1] + separators + [w]
    panels = [
        [[grid[r][c] for c in range(bounds[i] + 1, bounds[i + 1])]
         for r in range(h)]
        for i in range(len(bounds) - 1)
    ]

    out = [[0] * len(panels[0][0]) for _ in range(h)]
    for i in [2, 3, 0, 1]:
        for r in range(h):
            for c in range(len(out[0])):
                if out[r][c] == 0 and panels[i][r][c] != 0:
                    out[r][c] = panels[i][r][c]
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    sources = {}

    # Find one-cell gaps between same-colored parts of horizontal bars.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                sources.setdefault(c, []).append((r, color))

    # Extend each gap upward, with each bar's color occupying the interval
    # up to the previous bar in that same column.
    for c, bars in sources.items():
        bars.sort()
        previous = -1
        for r, color in bars:
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r

    return out

def transform(grid):
    h = len(grid) // 4
    w = len(grid[0])
    # Overlay the four panels, with priority 5 > 4 > 8 > 2.
    priority = {0: 0, 2: 1, 8: 2, 4: 3, 5: 4}
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append(max((grid[k * h + r][c] for k in range(4)),
                           key=lambda color: priority[color]))
        out.append(row)
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h = len(out)
    w = len(out[0])

    for c in range(w):
        if out[h - 1][c] != 5:
            continue
        below = None
        for r in range(h - 1, -1, -1):
            if out[r][c] != 0:
                below = out[r][c]
            elif below is not None:
                out[r][c] = below
    return out

def transform(grid):
